-- 컬렉션 조회는 반대편에서

@Test
void 거울로_조회() {
    Team team = new Team("F팀");
    em.persist(team);
    em.persist(new Member("a", 20, team));
    em.persist(new Member("b", 21, team));
    em.flush(); em.clear();

    Team found = em.find(Team.class, team.getId());
    System.out.println("--- 컬렉션을 읽는다 ---");
    System.out.println("회원 수: " + found.getMembers().size());
}

